# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


# ---
def build_student(last_name: str, first_name: str) -> Student:
    return Student(f"{last_name}{first_name}", last_name, first_name, "A")


class SeatRowTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            build_student("Halloway", "Juno"),
            build_student("Dunmere", "Piet"),
            build_student("Ash", "Ren")
        ]

    def test_sorts_by_last_name_then_fills_rows(self):
        self.assertEqual(
            seat_rows(self.students, 2),
            ["Row 1: Ash, Ren | Dunmere, Piet", "Row 2: Halloway, Juno"]
        )

    def test_one_row_when_seats_cover_everyone(self):
        self.assertEqual(
            seat_rows(self.students, 5),
            ["Row 1: Ash, Ren | Dunmere, Piet | Halloway, Juno"]
        )

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, -1)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
